export const GATT_UNAVAILABLE_MESSAGE =
  'Bluetooth GATT is not available on this device.';

export const GATT_DISCONNECTED_MESSAGE =
  'Bluetooth device is disconnected. Please reconnect the device.';

export class BleConnector {
  constructor() {
    /** @type {((device: BluetoothDevice) => void) | null} */
    this._onDisconnect = null;
    /** @type {BluetoothDevice | null} */
    this._device = null;
    /** @type {BluetoothRemoteGATTServer | null} */
    this._server = null;
    /** @type {Promise<BluetoothRemoteGATTServer> | null} */
    this._connectingPromise = null;
  }

  /**
   * @param {BluetoothDevice} device
   * @returns {Promise<BluetoothRemoteGATTServer>}
   */
  async connect(device) {
    if (this._connectingPromise) {
      return this._connectingPromise;
    }

    this._connectingPromise = this._connectInternal(device).finally(() => {
      this._connectingPromise = null;
    });

    return this._connectingPromise;
  }

  /**
   * @param {BluetoothDevice} device
   * @returns {Promise<BluetoothRemoteGATTServer>}
   */
  async _connectInternal(device) {
    if (!device?.gatt) {
      this._clearConnectionRefs();
      throw new Error(GATT_UNAVAILABLE_MESSAGE);
    }

    this._device = device;
    this._ensureDisconnectListener(device);

    let server;

    if (device.gatt.connected) {
      server = device.gatt;
    } else {
      // Drop any stale GATT handle before opening a fresh connection.
      this._server = null;
      try {
        server = await device.gatt.connect();
      } catch (err) {
        this._clearConnectionRefs(false);
        throw new Error(GATT_DISCONNECTED_MESSAGE, { cause: err });
      }
    }

    if (!server?.connected) {
      this._clearConnectionRefs(false);
      throw new Error(GATT_DISCONNECTED_MESSAGE);
    }

    this._server = server;
    return server;
  }

  /**
   * True only when Web Bluetooth reports an active GATT link.
   * @returns {boolean}
   */
  isGattConnected() {
    return Boolean(this._device?.gatt?.connected && this._server?.connected);
  }

  /**
   * Active GATT server if connected; otherwise null.
   * @returns {BluetoothRemoteGATTServer | null}
   */
  getConnectedServer() {
    if (this.isGattConnected()) {
      return this._server;
    }
    // Stale handle — never return a disconnected server to callers.
    if (this._server && !this._server.connected) {
      this._server = null;
    }
    return null;
  }

  _ensureDisconnectListener(device) {
    device.removeEventListener('gattserverdisconnected', this._handleDisconnect);
    device.addEventListener('gattserverdisconnected', this._handleDisconnect);
  }

  /**
   * Drop cached GATT server without removing the device (allows partner retry).
   */
  invalidateServer() {
    this._server = null;
  }

  /**
   * @param {boolean} [keepDevice=true] Keep device ref for reconnect attempts.
   */
  _clearConnectionRefs(keepDevice = true) {
    this._server = null;
    if (!keepDevice) {
      if (this._device) {
        this._device.removeEventListener('gattserverdisconnected', this._handleDisconnect);
      }
      this._device = null;
    }
  }

  _handleDisconnect = () => {
    // Critical: clear stale GATT immediately so startMeasurement cannot reuse it.
    this._server = null;

    if (this._onDisconnect && this._device) {
      this._onDisconnect(this._device);
    }
  };

  /**
   * @param {(device: BluetoothDevice) => void} callback
   */
  onDisconnected(callback) {
    this._onDisconnect = callback;
  }

  async disconnect() {
    const device = this._device;
    if (device) {
      device.removeEventListener('gattserverdisconnected', this._handleDisconnect);
      try {
        if (device.gatt?.connected) {
          device.gatt.disconnect();
        }
      } catch {
        /* ignore */
      }
    }
    this._device = null;
    this._server = null;
    this._connectingPromise = null;
  }

  get device() {
    return this._device;
  }

  get server() {
    // Prefer live Web Bluetooth state over a cached handle.
    return this.getConnectedServer();
  }
}

export default BleConnector;
