import axios from 'axios';
import PacketEncryption from '../crypto/encryption.js';

export class ApiClient {
  /**
   * @param {{ apiKey: string, baseUrl?: string, timeout?: number }} options
   */
  constructor({ apiKey, baseUrl = 'https://api.dr-odin.com', timeout = 30000 }) {
    this.apiKey = apiKey;
    this.baseUrl = baseUrl.replace(/\/$/, '');
    this.encryption = new PacketEncryption(apiKey);

    this.http = axios.create({
      baseURL: this.baseUrl,
      timeout,
      headers: {
        'Content-Type': 'application/json',
        'X-API-Key': apiKey,
      },
    });
  }

  async initialize() {
    const { data } = await this.http.get('/api/parser/initialize');
    return data;
  }

  async getStartCommands(deviceType, sessionId) {
    const { data } = await this.http.get(`/api/parser/commands/${deviceType}`, {
      params: { sessionId },
    });
    return data.commands || [];
  }

  /**
   * @param {{ patientName: string, mobile: string, deviceType?: string }} payload
   */
  async startSession(payload) {
    const { data } = await this.http.post('/api/parser/sessions', payload);
    return data;
  }

  async getSession(sessionId) {
    const { data } = await this.http.get(`/api/parser/sessions/${sessionId}`);
    return data;
  }

  async endSession(sessionId) {
    const { data } = await this.http.post(`/api/parser/sessions/${sessionId}/end`);
    return data;
  }

  /**
   * @param {string} deviceType
   * @param {Uint8Array} packetBytes
   * @param {object} context
   * @param {string} [deviceId]
   * @param {string} [sessionId]
   */
  async parsePacket(deviceType, packetBytes, context = {}, deviceId = null, sessionId = null) {
    const encryptedPacket = await this.encryption.encrypt(packetBytes);
    const { data } = await this.http.post('/api/parser/parse', {
      deviceType,
      encryptedPacket,
      context,
      deviceId,
      sessionId,
    });
    return data;
  }
}

export default ApiClient;
