import DrOdinEmitter from '../events/emitter.js';
import ApiClient from '../api/client.js';
import BleScanner from '../bluetooth/scanner.js';
import BleConnector, {
  GATT_DISCONNECTED_MESSAGE,
} from '../bluetooth/connector.js';
import NotificationManager from '../bluetooth/notifications.js';
import {
  GattError,
  GATT_ERROR_CODES,
  isGattTimeoutError,
} from '../bluetooth/gattErrors.js';
import ReconnectManager from '../bluetooth/reconnect.js';
import ParseQueue from '../bluetooth/parseQueue.js';
import { resolveProfiles } from '../bluetooth/deviceRegistry.js';
import validateSessionInput from '../session/validateSession.js';

/** BLE use is blocked until startSession({ patientName, mobile }) succeeds. */
export const SESSION_REQUIRED_MESSAGE =
  'Patient session required. Call startSession({ patientName, mobile }) before using Bluetooth.';

const DEVICE_EVENTS = {
  weight_scale: 'weight',
  bp_monitor: 'bp',
  pulse_oximeter: 'spo2',
  digital_thermometer: 'temperature',
  infrared_thermometer: 'temperature',
  wearable_thermometer: 'temperature',
  glucometer: 'glucose',
  fetal_doppler: 'fetal',
};

/**
 * Dr. Odin Web Bluetooth SDK
 *
 * Partners integrate medical devices without access to BLE parsing logic.
 * Raw packets are AES-256-GCM encrypted and parsed on the backend.
 *
 * @example
 * const sdk = new DrOdinSDK({ apiKey: 'drod_...', deviceType: 'weight_scale' });
 * await sdk.initialize();
 * await sdk.startSession({ patientName: 'Jane', mobile: '9876543210' });
 * await sdk.connect();
 * sdk.onWeight(data => console.log(data.weight));
 * await sdk.startMeasurement();
 */
export class DrOdinSDK extends DrOdinEmitter {
  /**
   * @param {import('../../types/index.d.ts').DrOdinSDKOptions} options
   */
  constructor(options = {}) {
    super();

    if (!options.apiKey) {
      throw new Error('apiKey is required');
    }

    this.apiKey = options.apiKey;
    this.baseUrl = options.baseUrl || 'http://localhost:8080';
    this.deviceType = options.deviceType || null;
    this.autoReconnect = options.autoReconnect !== false;

    this._client = new ApiClient({ apiKey: this.apiKey, baseUrl: this.baseUrl });
    this._scanner = new BleScanner();
    this._connector = new BleConnector();
    this._notifications = new NotificationManager();
    this._reconnect = new ReconnectManager(options.reconnect);
    this._parseQueue = new ParseQueue({
      getDeviceType: () => this.deviceType,
      send: bytes => this._parseAndEmit(bytes),
    });

    this._initialized = false;
    this._measuring = false;
    this._manualDisconnect = false;
    this._parserContext = {};
    this._config = null;
    this._profile = null;
    this._unsubscribe = null;
    this._sessionId = null;
    this._session = null;
    /** @type {boolean} Patient session (name + mobile) is mandatory before any BLE use. */
    this._sessionRequired = true;
    /** Suppress duplicate failure when OS disconnect races a GATT timeout. */
    this._ignoreNextDisconnect = false;
    /** Ensures only one failure is reported for a subscribe attempt. */
    this._subscribeFailureSettled = false;
  }

  /**
   * Fetch partner config and device profiles from backend.
   * @returns {Promise<object>}
   */
  async initialize() {
    const config = await this._client.initialize();
    this._config = config;

    const profiles = resolveProfiles(
      config.deviceProfiles,
      config.partner?.allowedDevices || config.allowedDevices,
    );

    this._scanner.setProfiles(profiles);
    this._initialized = true;
    this._sessionRequired = config.sessionRequired !== false;

    this.emit('initialized', {
      partner: config.partner,
      deviceProfiles: profiles,
      sessionRequired: this._sessionRequired,
    });
    return config;
  }

  /** Whether an active patient session exists (required for Bluetooth). */
  hasActiveSession() {
    return Boolean(this._sessionId);
  }

  /**
   * Start a patient session (name + mobile required before BLE).
   * @param {{ patientName: string, mobile: string, deviceType?: string }} payload
   */
  async startSession(payload) {
    this._ensureInitialized();

    const validated = validateSessionInput(payload);
    const result = await this._client.startSession(validated);

    this._sessionId = result.sessionId;
    this._session = result;
    this.emit('session:start', result);
    return result;
  }

  /** @returns {object | null} Active session metadata */
  getSession() {
    return this._session;
  }

  /** End the active session and disconnect any BLE device. */
  async endSession() {
    if (!this._sessionId) {
      throw new Error('No active session to end.');
    }

    if (this._connector.device || this._measuring) {
      await this.disconnect();
    }

    const result = await this._client.endSession(this._sessionId);
    this.emit('session:end', result);
    this._sessionId = null;
    this._session = null;
    return result;
  }

  _ensureSession() {
    if (this._sessionRequired && !this._sessionId) {
      throw new Error(SESSION_REQUIRED_MESSAGE);
    }
  }

  /**
   * Open Web Bluetooth device picker.
   * @param {string} [deviceType]
   * @returns {Promise<{ device: BluetoothDevice, profile: object }>}
   */
  async scan(deviceType = this.deviceType) {
    this._ensureInitialized();
    this._ensureSession();
    const result = deviceType ? await this._scanner.scan(deviceType) : await this._scanner.scan();
    this.emit('scan:complete', result);
    return result;
  }

  /**
   * Connect to a BLE device.
   * @param {{ deviceType?: string, device?: BluetoothDevice, profile?: object }} [options]
   */
  async connect(options = {}) {
    this._ensureInitialized();
    this._ensureSession();
    this._manualDisconnect = false;
    this._reconnect.reset();

    let { device, profile } = options;
    const deviceType = options.deviceType || this.deviceType;

    if (!device) {
      const scanned = await this.scan(deviceType);
      device = scanned.device;
      profile = scanned.profile;
    }

    this._connector.onDisconnected(d => this._handleUnexpectedDisconnect(d));

    const server = await this._connector.connect(device);
    this._profile = profile;
    this.deviceType = profile?.deviceType || deviceType;

    this.emit('connect', {
      deviceId: device.id,
      deviceName: device.name,
      deviceType: this.deviceType,
    });

    return { device, profile, server };
  }

  /**
   * Disconnect from the current device.
   */
  async disconnect() {
    this._manualDisconnect = true;
    this._reconnect.cancel();
    this._measuring = false;
    this._parseQueue.close();

    if (this._unsubscribe) {
      await this._unsubscribe();
      this._unsubscribe = null;
    }

    await this._notifications.stopAll();
    await this._connector.disconnect();

    this.emit('disconnect', { reason: 'manual' });
  }

  /**
   * Ensure a live GATT server before any service/characteristic access.
   * Reconnects with the existing device when the previous link went stale.
   * @returns {Promise<BluetoothRemoteGATTServer>}
   */
  async _ensureLiveGattServer() {
    let server = this._connector.getConnectedServer();
    if (server?.connected) {
      return server;
    }

    // Drop notification handles tied to the dead GATT connection.
    if (this._unsubscribe) {
      try {
        await this._unsubscribe();
      } catch {
        /* ignore */
      }
      this._unsubscribe = null;
    }
    await this._notifications.stopAll();

    const device = this._connector.device;
    if (!device?.gatt) {
      throw new Error(GATT_DISCONNECTED_MESSAGE);
    }

    try {
      server = await this._connector.connect(device);
    } catch (err) {
      throw new Error(GATT_DISCONNECTED_MESSAGE, { cause: err });
    }

    if (!server?.connected) {
      throw new Error(GATT_DISCONNECTED_MESSAGE);
    }

    return server;
  }

  /**
   * Cleanup after a failed subscribe / startMeasurement GATT path.
   * Clears connection-specific state without blind disconnect loops.
   * @param {unknown} err
   * @returns {Error}
   */
  async _finalizeSubscribeFailure(err) {
    if (this._subscribeFailureSettled) {
      return err instanceof Error ? err : new Error(String(err));
    }
    this._subscribeFailureSettled = true;

    this._measuring = false;
    this._parseQueue.close();
    this._unsubscribe = null;
    await this._notifications.stopAll().catch(() => {});

    const finalErr =
      err instanceof GattError
        ? err
        : isGattTimeoutError(err)
          ? err
          : /gatt server is disconnected|not connected|disconnected/i.test(
                String(err?.message || err),
              )
            ? new GattError(
                GATT_ERROR_CODES.DISCONNECTED,
                GATT_DISCONNECTED_MESSAGE,
                err instanceof Error ? err : undefined,
              )
            : err instanceof Error
              ? err
              : new Error(String(err));

    // Timeout or explicit disconnect during subscribe: clear stale GATT and
    // ignore the near-simultaneous gattserverdisconnected race.
    if (isGattTimeoutError(finalErr) || finalErr?.code === GATT_ERROR_CODES.DISCONNECTED) {
      this._ignoreNextDisconnect = true;
      this._connector.invalidateServer();
      this._reconnect.cancel();
    }

    this.emitError(finalErr);
    return finalErr;
  }

  /**
   * Subscribe to BLE notifications and stream encrypted packets to the backend.
   */
  async startMeasurement() {
    this._ensureInitialized();
    this._ensureSession();

    if (!this._profile) {
      throw new Error('Not connected. Call connect() first.');
    }

    if (this._measuring) return;

    this._subscribeFailureSettled = false;

    let server;
    try {
      server = await this._ensureLiveGattServer();
    } catch (err) {
      const finalErr = await this._finalizeSubscribeFailure(err);
      throw finalErr;
    }

    this._parserContext = {};
    this._parseQueue.open();

    try {
      const commands = await this._client.getStartCommands(this.deviceType, this._sessionId);
      for (const cmd of commands) {
        // Re-check live link before each GATT write.
        server = await this._ensureLiveGattServer();
        await this._notifications.writeCommand(server, this._profile, cmd);
      }

      server = await this._ensureLiveGattServer();
      this._unsubscribe = await this._notifications.subscribe(
        server,
        this._profile,
        (bytes, meta) => this._onRawPacket(bytes, meta),
        {
          deviceType: this.deviceType,
          device: this._connector.device,
        },
      );
    } catch (err) {
      const finalErr = await this._finalizeSubscribeFailure(err);
      throw finalErr;
    }

    this._measuring = true;
    this.emit('measurement:start', { deviceType: this.deviceType });
  }

  /** Stop BLE notifications. */
  async stopMeasurement() {
    if (this._unsubscribe) {
      await this._unsubscribe();
      this._unsubscribe = null;
    }
    this._measuring = false;
    this._parseQueue.close();
    this.emit('measurement:stop', { deviceType: this.deviceType });
  }

  /**
   * Enqueue BLE bytes for throttled / serialized parse (streaming-safe).
   * @param {Uint8Array} bytes
   * @param {object} _meta
   */
  _onRawPacket(bytes, _meta) {
    if (!this._measuring) return;
    this._parseQueue.enqueue(bytes);
  }

  /**
   * @param {Uint8Array} bytes
   */
  async _parseAndEmit(bytes) {
    if (!this._measuring) return;

    try {
      const response = await this._client.parsePacket(
        this.deviceType,
        bytes,
        this._parserContext,
        this._connector.device?.id,
        this._sessionId,
      );

      if (response.context) {
        this._parserContext = response.context;
      }

      if (response.commands?.length && this._profile) {
        const liveServer = this._connector.getConnectedServer();
        if (!liveServer?.connected) {
          return;
        }
        for (const cmd of response.commands) {
          await this._notifications.writeCommand(liveServer, this._profile, cmd);
        }
      }

      if (response.data) {
        this._emitReading(response.data);
      }

      if (response.meta) {
        this.emit('meta', response.meta);
      }
    } catch (err) {
      this.emitError(err);
    }
  }

  /** @param {object} data */
  _emitReading(data) {
    const event = DEVICE_EVENTS[this.deviceType];
    if (event) {
      this.emit(event, data);
    }
    this.emit('data', { deviceType: this.deviceType, ...data });
  }

  /** @param {BluetoothDevice} device */
  _handleUnexpectedDisconnect(device) {
    // Connector already nulled _server in its gattserverdisconnected handler.
    const ignoreAsRace = this._ignoreNextDisconnect;
    this._ignoreNextDisconnect = false;

    this.emit('disconnect', {
      reason: ignoreAsRace ? 'gatt_operation_failed' : 'gatt_disconnected',
      deviceName: device.name,
    });
    const wasMeasuring = this._measuring;
    this._measuring = false;
    this._parseQueue.close();

    if (this._unsubscribe) {
      this._unsubscribe();
      this._unsubscribe = null;
    }
    // Best-effort cleanup of any leftover notification stoppers.
    this._notifications.stopAll().catch(() => {});

    // Do not auto-reconnect after a subscribe timeout race — partner must retry.
    if (ignoreAsRace) {
      this._reconnect.cancel();
      return;
    }

    if (!this._manualDisconnect && this.autoReconnect) {
      this._reconnect.schedule(async () => {
        this.emit('reconnect:attempt');
        await this.connect({
          device,
          profile: this._profile,
        });
        if (wasMeasuring) {
          await this.startMeasurement();
        }
        this.emit('reconnect:success');
      }).then(ok => {
        if (!ok) this.emit('reconnect:failed');
      });
    }
  }

  _ensureInitialized() {
    if (!this._initialized) {
      throw new Error('SDK not initialized. Call initialize() first.');
    }
  }

  /** @param {(data: import('../../types/index.d.ts').WeightReading) => void} callback */
  onWeight(callback) {
    return this.on('weight', callback);
  }

  /** @param {(data: import('../../types/index.d.ts').BPReading) => void} callback */
  onBP(callback) {
    return this.on('bp', callback);
  }

  /** @param {(data: import('../../types/index.d.ts').Spo2Reading) => void} callback */
  onSpo2(callback) {
    return this.on('spo2', callback);
  }

  /** @param {(data: object) => void} callback */
  onFetal(callback) {
    return this.on('fetal', callback);
  }

  /** @param {(data: import('../../types/index.d.ts').TemperatureReading) => void} callback */
  onTemperature(callback) {
    return this.on('temperature', callback);
  }

  /** @param {(data: import('../../types/index.d.ts').GlucoseReading) => void} callback */
  onGlucose(callback) {
    return this.on('glucose', callback);
  }

  /** @param {(event: import('../../types/index.d.ts').DisconnectEvent) => void} callback */
  onDisconnect(callback) {
    return this.on('disconnect', callback);
  }

  /** @param {(error: Error) => void} callback */
  onError(callback) {
    return this.on('error', callback);
  }

  /** @param {(info: import('../../types/index.d.ts').SessionInfo) => void} callback */
  onSessionStart(callback) {
    return this.on('session:start', callback);
  }

  /** @param {(info: import('../../types/index.d.ts').SessionInfo) => void} callback */
  onSessionEnd(callback) {
    return this.on('session:end', callback);
  }
}

export default DrOdinSDK;
