const MOBILE_PATTERN = /^[6-9]\d{9}$/;

/**
 * Validate patient session input before startSession (SDK + shared rules with backend).
 * @param {{ patientName?: string, mobile?: string, deviceType?: string }} payload
 */
export function validateSessionInput(payload = {}) {
  const patientName = payload.patientName?.trim();
  const mobile = payload.mobile?.trim().replace(/\s+/g, '');

  if (!patientName || patientName.length < 2) {
    throw new Error('Patient name is required (minimum 2 characters).');
  }

  if (!mobile || !MOBILE_PATTERN.test(mobile)) {
    throw new Error('Valid 10-digit mobile number is required.');
  }

  return {
    patientName,
    mobile,
    deviceType: payload.deviceType?.trim() || undefined,
  };
}

export default validateSessionInput;
