/**
 * Structured Web Bluetooth / GATT errors for partners.
 * Emitted via onError(); `code` distinguishes timeout vs physical disconnect.
 */
export const GATT_ERROR_CODES = {
  SERVICE_DISCOVERY_TIMEOUT: 'GATT_SERVICE_DISCOVERY_TIMEOUT',
  CHARACTERISTIC_DISCOVERY_TIMEOUT: 'GATT_CHARACTERISTIC_DISCOVERY_TIMEOUT',
  NOTIFICATION_SUBSCRIBE_TIMEOUT: 'GATT_NOTIFICATION_SUBSCRIBE_TIMEOUT',
  DISCONNECTED: 'GATT_DISCONNECTED',
};

export class GattError extends Error {
  /**
   * @param {string} code
   * @param {string} message
   * @param {Error} [cause]
   */
  constructor(code, message, cause) {
    super(message);
    this.name = 'GattError';
    this.code = code;
    if (cause !== undefined) {
      this.cause = cause;
    }
  }
}

export function isGattTimeoutError(err) {
  const code = err?.code;
  return (
    code === GATT_ERROR_CODES.SERVICE_DISCOVERY_TIMEOUT ||
    code === GATT_ERROR_CODES.CHARACTERISTIC_DISCOVERY_TIMEOUT ||
    code === GATT_ERROR_CODES.NOTIFICATION_SUBSCRIBE_TIMEOUT
  );
}

export default GattError;
