/**
 * AES-256-GCM encryption for raw BLE packets.
 * Key: SHA-256(apiKey) — matches backend parser-service.
 */
export class PacketEncryption {
  constructor(apiKey) {
    this.apiKey = apiKey;
    /** @type {CryptoKey | null} */
    this._cryptoKey = null;
  }

  async _getKey() {
    if (this._cryptoKey) return this._cryptoKey;
    const encoder = new TextEncoder();
    const hash = await crypto.subtle.digest('SHA-256', encoder.encode(this.apiKey));
    this._cryptoKey = await crypto.subtle.importKey(
      'raw',
      hash,
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt'],
    );
    return this._cryptoKey;
  }

  /**
   * @param {Uint8Array | number[]} packetBytes
   * @returns {Promise<{ iv: string, ciphertext: string, authTag: string }>}
   */
  async encrypt(packetBytes) {
    const key = await this._getKey();
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const plaintext = packetBytes instanceof Uint8Array ? packetBytes : new Uint8Array(packetBytes);

    const encrypted = await crypto.subtle.encrypt(
      { name: 'AES-GCM', iv, tagLength: 128 },
      key,
      plaintext,
    );

    const full = new Uint8Array(encrypted);
    const tagLength = 16;
    const ciphertext = full.slice(0, full.length - tagLength);
    const authTag = full.slice(full.length - tagLength);

    return {
      iv: btoa(String.fromCharCode(...iv)),
      ciphertext: btoa(String.fromCharCode(...ciphertext)),
      authTag: btoa(String.fromCharCode(...authTag)),
    };
  }
}

export default PacketEncryption;
