import { GattError, GATT_ERROR_CODES } from './gattErrors.js';

/** Fail fast — do not wait for the browser ~30s GATT watchdog. */
export const GATT_OPERATION_TIMEOUT_MS = 10000;

/**
 * @param {Promise<T>} promise
 * @param {number} timeoutMs
 * @param {() => Error} createTimeoutError
 * @param {() => boolean} [isDisconnected]
 * @returns {Promise<T>}
 * @template T
 */
export function withTimeout(promise, timeoutMs, createTimeoutError, isDisconnected) {
  return new Promise((resolve, reject) => {
    let settled = false;

    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      // Prefer physical-disconnect classification if link already dropped.
      if (typeof isDisconnected === 'function' && isDisconnected()) {
        reject(
          new GattError(
            GATT_ERROR_CODES.DISCONNECTED,
            'Bluetooth device is disconnected. Please reconnect the device.',
          ),
        );
        return;
      }
      reject(createTimeoutError());
    }, timeoutMs);

    Promise.resolve(promise).then(
      value => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        resolve(value);
      },
      err => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        reject(err);
      },
    );
  });
}

/**
 * @param {DataView} value
 * @returns {Uint8Array}
 */
export function dataViewToBytes(value) {
  return new Uint8Array(value.buffer, value.byteOffset, value.byteLength);
}

export class NotificationManager {
  constructor() {
    /** @type {Array<() => void | Promise<void>>} */
    this._unsubscribers = [];
  }

  /**
   * @param {BluetoothRemoteGATTServer} server
   */
  _assertConnected(server) {
    if (!server?.connected) {
      throw new GattError(
        GATT_ERROR_CODES.DISCONNECTED,
        'Bluetooth device is disconnected. Please reconnect the device.',
      );
    }
  }

  /**
   * @param {BluetoothRemoteGATTServer} server
   * @returns {() => boolean}
   */
  _disconnectedChecker(server) {
    return () => !server?.connected;
  }

  /**
   * @param {BluetoothRemoteGATTServer} server
   * @param {object} profile
   * @param {(bytes: Uint8Array, meta: object) => void} onPacket
   * @param {{ deviceType?: string, device?: BluetoothDevice | null }} [context]
   */
  async subscribe(server, profile, onPacket, context = {}) {
    this._assertConnected(server);
    const stops = [];
    const isDisconnected = this._disconnectedChecker(server);
    const deviceType = context.deviceType || profile?.deviceType || 'unknown';
    const device = context.device;
    const timeoutMs = context.timeoutMs ?? GATT_OPERATION_TIMEOUT_MS;

    if (deviceType === 'fetal_doppler') {
      console.log(
        '[DrOdinSDK] Fetal Doppler subscribe\n' +
          `deviceType=${deviceType}\n` +
          `device=${device?.name || 'unknown'}\n` +
          `deviceId=${device?.id || 'unknown'}\n` +
          `serverConnected=${Boolean(server?.connected)}`,
      );
    }

    try {
      for (const entry of profile.notifyCharacteristics || []) {
        this._assertConnected(server);

        const serviceUuid = entry.service;
        const characteristicUuid = entry.characteristic;

        if (deviceType === 'fetal_doppler') {
          console.log(
            `[DrOdinSDK] Fetal Doppler subscribe service=${serviceUuid} characteristic=${characteristicUuid}`,
          );
        }

        console.log('[DrOdinSDK] Discovering GATT service:', serviceUuid);
        let service;
        try {
          service = await withTimeout(
            server.getPrimaryService(serviceUuid),
            timeoutMs,
            () =>
              new GattError(
                GATT_ERROR_CODES.SERVICE_DISCOVERY_TIMEOUT,
                `GATT service discovery timed out after ${timeoutMs}ms: ${serviceUuid}`,
              ),
            isDisconnected,
          );
        } catch (err) {
          console.error('[DrOdinSDK] GATT service discovery timeout/failure:', serviceUuid, err);
          throw this._normalizeGattFailure(err, 'service');
        }
        console.log('[DrOdinSDK] GATT service discovered:', serviceUuid);

        this._assertConnected(server);

        console.log('[DrOdinSDK] Discovering GATT characteristic:', characteristicUuid);
        let characteristic;
        try {
          characteristic = await withTimeout(
            service.getCharacteristic(characteristicUuid),
            timeoutMs,
            () =>
              new GattError(
                GATT_ERROR_CODES.CHARACTERISTIC_DISCOVERY_TIMEOUT,
                `GATT characteristic discovery timed out after ${timeoutMs}ms: ${characteristicUuid}`,
              ),
            isDisconnected,
          );
        } catch (err) {
          console.error(
            '[DrOdinSDK] GATT characteristic discovery timeout/failure:',
            characteristicUuid,
            err,
          );
          throw this._normalizeGattFailure(err, 'characteristic');
        }
        console.log('[DrOdinSDK] GATT characteristic discovered:', characteristicUuid);

        this._assertConnected(server);

        console.log('[DrOdinSDK] Starting notifications:', characteristic.uuid || characteristicUuid);
        try {
          await withTimeout(
            characteristic.startNotifications(),
            timeoutMs,
            () =>
              new GattError(
                GATT_ERROR_CODES.NOTIFICATION_SUBSCRIBE_TIMEOUT,
                `GATT notification subscription timed out after ${timeoutMs}ms`,
              ),
            isDisconnected,
          );
        } catch (err) {
          console.error(
            '[DrOdinSDK] GATT notification subscribe timeout/failure:',
            characteristicUuid,
            err,
          );
          throw this._normalizeGattFailure(err, 'notify');
        }
        console.log('[DrOdinSDK] Notifications started:', characteristic.uuid || characteristicUuid);

        const handler = event => {
          const bytes = dataViewToBytes(event.target.value);
          onPacket(bytes, {
            serviceUuid,
            characteristicUuid,
          });
        };

        characteristic.addEventListener('characteristicvaluechanged', handler);

        stops.push(async () => {
          characteristic.removeEventListener('characteristicvaluechanged', handler);
          try {
            await characteristic.stopNotifications();
          } catch {
            /* ignore */
          }
        });
      }
    } catch (err) {
      // Cleanup any partial subscriptions from this attempt.
      await Promise.all(stops.map(stop => Promise.resolve(stop()).catch(() => {})));
      throw err;
    }

    if (!stops.length) {
      throw new GattError(
        GATT_ERROR_CODES.NOTIFICATION_SUBSCRIBE_TIMEOUT,
        'GATT notification subscription failed: no notify characteristics subscribed',
      );
    }

    this._unsubscribers.push(...stops);
    return () => this._unsubscribe(stops);
  }

  /**
   * Preserve GattError codes; map native disconnect-ish failures.
   * @param {unknown} err
   * @param {'service' | 'characteristic' | 'notify'} _phase
   */
  _normalizeGattFailure(err, _phase) {
    if (err instanceof GattError) {
      return err;
    }
    const message = String(err?.message || err);
    if (/gatt server is disconnected|not connected|disconnected/i.test(message)) {
      return new GattError(
        GATT_ERROR_CODES.DISCONNECTED,
        'Bluetooth device is disconnected. Please reconnect the device.',
        err instanceof Error ? err : undefined,
      );
    }
    return err instanceof Error ? err : new Error(String(err));
  }

  /**
   * Write only to configured writeCharacteristics.
   * Never fall back to notify-only characteristics (e.g. fetal_doppler FFE4).
   * @param {BluetoothRemoteGATTServer} server
   * @param {object} profile
   * @param {number[] | Uint8Array} commandBytes
   */
  async writeCommand(server, profile, commandBytes) {
    this._assertConnected(server);

    const writes = profile.writeCharacteristics || [];
    if (!writes.length) {
      // Notification-only profiles (fetal_doppler, glucometer FFF4) — no writable characteristic.
      return;
    }

    const target = writes[0];
    const isDisconnected = this._disconnectedChecker(server);

    const service = await withTimeout(
      server.getPrimaryService(target.service),
      GATT_OPERATION_TIMEOUT_MS,
      () =>
        new GattError(
          GATT_ERROR_CODES.SERVICE_DISCOVERY_TIMEOUT,
          `GATT service discovery timed out after ${GATT_OPERATION_TIMEOUT_MS}ms: ${target.service}`,
        ),
      isDisconnected,
    );

    const characteristic = await withTimeout(
      service.getCharacteristic(target.characteristic),
      GATT_OPERATION_TIMEOUT_MS,
      () =>
        new GattError(
          GATT_ERROR_CODES.CHARACTERISTIC_DISCOVERY_TIMEOUT,
          `GATT characteristic discovery timed out after ${GATT_OPERATION_TIMEOUT_MS}ms: ${target.characteristic}`,
        ),
      isDisconnected,
    );

    const props = characteristic.properties;
    const canWrite = Boolean(props?.write);
    const canWriteWithoutResponse = Boolean(props?.writeWithoutResponse);

    // Notify-only chars (e.g. AC307 FFF4) — skip instead of throwing "not permitted".
    if (props && !canWrite && !canWriteWithoutResponse) {
      console.warn(
        '[DrOdinSDK] Skipping write — characteristic is not writable:',
        target.characteristic,
      );
      return;
    }

    const payload = new Uint8Array(commandBytes);
    if (canWriteWithoutResponse && !canWrite && typeof characteristic.writeValueWithoutResponse === 'function') {
      await characteristic.writeValueWithoutResponse(payload);
      return;
    }

    await characteristic.writeValue(payload);
  }

  /** @param {Array<() => void | Promise<void>>} stops */
  _unsubscribe(stops) {
    stops.forEach(stop => stop());
    this._unsubscribers = this._unsubscribers.filter(s => !stops.includes(s));
  }

  async stopAll() {
    await Promise.all(this._unsubscribers.map(s => Promise.resolve(s()).catch(() => {})));
    this._unsubscribers = [];
  }
}

export default NotificationManager;
