export class BleScanner {
  constructor() {
    /** @type {import('../bluetooth/deviceRegistry.js').DEVICE_REGISTRY[]} */
    this._profiles = [];
  }

  /** @param {object[]} profiles */
  setProfiles(profiles) {
    this._profiles = profiles || [];
  }

  _assertSupport() {
    if (typeof navigator === 'undefined' || !navigator.bluetooth) {
      throw new Error(
        'Web Bluetooth is not supported. Use Chrome, Edge, or Opera over HTTPS (or localhost).',
      );
    }
  }

  /**
   * @param {string} [deviceType]
   */
  async scan(deviceType) {
    this._assertSupport();

    if (deviceType) {
      const profile = this._profiles.find(p => p.deviceType === deviceType);
      if (!profile) {
        throw new Error(`Device type "${deviceType}" is not enabled for your account`);
      }
      return this._requestDevice(profile);
    }

    return this._scanAny();
  }

  async _requestDevice(profile) {
    const filters = [];
    if (profile.filters?.namePrefix) {
      filters.push({ namePrefix: profile.filters.namePrefix });
    }
    if (profile.filters?.services?.length) {
      filters.push({ services: profile.filters.services });
    }

    const optionalServices = [
      ...new Set([
        ...(profile.filters?.services || []),
        ...(profile.notifyCharacteristics || []).map(c => c.service),
        ...(profile.writeCharacteristics || []).map(c => c.service),
      ]),
    ];

    const device = await navigator.bluetooth.requestDevice({
      filters: filters.length ? filters : undefined,
      optionalServices,
      acceptAllDevices: !filters.length,
    });

    return { device, profile };
  }

  async _scanAny() {
    const allServices = [
      ...new Set(this._profiles.flatMap(p => p.filters?.services || [])),
    ];

    const device = await navigator.bluetooth.requestDevice({
      optionalServices: allServices,
      acceptAllDevices: true,
    });

    const profile =
      this._profiles.find(p => device.name?.startsWith(p.filters?.namePrefix || '\0')) ||
      this._profiles[0];

    if (!profile) {
      throw new Error('No matching device profile for your account');
    }

    return { device, profile };
  }
}

export default BleScanner;
