/** Device types that stream high-frequency BLE notifications. */
export const STREAMING_PARSE_POLICY = {
  pulse_oximeter: { strategy: 'latest', minIntervalMs: 300 },
  // Vitals-only: 0x70 → API; 0x71 audio stays on device (same as RN app)
  fetal_doppler: { strategy: 'fetal_vitals', minIntervalMs: 200 },
};

const FETAL_SYNC = 0xfe;
const FETAL_CMD_VITALS = 0x70;
const FETAL_CMD_AUDIO = 0x71;
const FETAL_MAX_PKT_LEN = 0xc8;

/**
 * @param {Uint8Array} a
 * @param {Uint8Array} b
 * @returns {Uint8Array}
 */
export function concatBytes(a, b) {
  const out = new Uint8Array(a.length + b.length);
  out.set(a, 0);
  out.set(b, a.length);
  return out;
}

/**
 * Pull complete 0x70 vitals frames out of a fetal BLE byte stream.
 * Discard 0x71 ADPCM audio frames (parsed/played only on device in RN).
 * @param {Uint8Array} bytes
 * @param {Uint8Array} [carry]
 * @returns {{ vitals: Uint8Array | null, carry: Uint8Array }}
 */
export function extractFetalVitalsBytes(bytes, carry = new Uint8Array(0)) {
  let rx = carry.length ? concatBytes(carry, bytes) : bytes.slice();
  const vitalsParts = [];

  while (rx.length >= 4) {
    if (rx[0] !== FETAL_SYNC) {
      rx = rx.subarray(1);
      continue;
    }

    const pktLen = rx[1];
    if (pktLen < 3 || pktLen > FETAL_MAX_PKT_LEN) {
      rx = rx.subarray(1);
      continue;
    }

    const totalLen = pktLen + 2;
    if (rx.length < totalLen) break;

    const frame = rx.subarray(0, totalLen);
    rx = rx.subarray(totalLen);
    const cmd = frame[2];

    if (cmd === FETAL_CMD_VITALS && pktLen >= 0x0a) {
      vitalsParts.push(frame.slice());
    }
    // cmd === FETAL_CMD_AUDIO → drop (audio is local-only, like RN)
  }

  // Cap carry so a corrupt stream cannot grow forever
  if (rx.length > 2048) {
    rx = rx.subarray(rx.length - 512);
  }

  if (!vitalsParts.length) {
    return { vitals: null, carry: rx.slice() };
  }

  let merged = vitalsParts[0];
  for (let i = 1; i < vitalsParts.length; i++) {
    merged = concatBytes(merged, vitalsParts[i]);
  }
  return { vitals: merged, carry: rx.slice() };
}

/**
 * @param {Uint8Array} bytes
 * @returns {Uint8Array}
 */
function copyBytes(bytes) {
  return bytes instanceof Uint8Array ? bytes.slice() : new Uint8Array(bytes);
}

/**
 * Serializes parse HTTP calls and coalesces streaming device packets so the
 * backend is not flooded (avoids 429 / timeouts).
 *
 * Fetal Doppler: only 0x70 vitals frames are sent to the parser (RN parity).
 * Pulse oximeter: keep latest packet every minIntervalMs.
 */
export class ParseQueue {
  /**
   * @param {{
   *   send: (bytes: Uint8Array) => Promise<void>,
   *   getDeviceType: () => string | null,
   * }} options
   */
  constructor({ send, getDeviceType }) {
    this._send = send;
    this._getDeviceType = getDeviceType;
    /** @type {Uint8Array[]} */
    this._fifo = [];
    /** @type {Uint8Array | null} */
    this._pending = null;
    /** @type {Uint8Array} */
    this._fetalCarry = new Uint8Array(0);
    this._busy = false;
    this._closed = false;
    this._lastSentAt = 0;
  }

  /** @param {Uint8Array} bytes */
  enqueue(bytes) {
    if (this._closed || !bytes?.length) return;

    const packet = copyBytes(bytes);
    const policy = STREAMING_PARSE_POLICY[this._getDeviceType()];

    if (!policy) {
      this._fifo.push(packet);
    } else if (policy.strategy === 'latest') {
      this._pending = packet;
    } else if (policy.strategy === 'fetal_vitals') {
      const { vitals, carry } = extractFetalVitalsBytes(packet, this._fetalCarry);
      this._fetalCarry = carry;
      if (!vitals?.length) {
        return; // audio-only chunk — no API call (matches RN)
      }
      this._pending = this._pending ? concatBytes(this._pending, vitals) : vitals;
    } else {
      // legacy concat
      this._pending = this._pending ? concatBytes(this._pending, packet) : packet;
    }

    this._pump();
  }

  clear() {
    this._fifo = [];
    this._pending = null;
    this._fetalCarry = new Uint8Array(0);
  }

  close() {
    this._closed = true;
    this.clear();
  }

  open() {
    this._closed = false;
    this.clear();
    this._lastSentAt = 0;
  }

  _hasWork() {
    return this._fifo.length > 0 || this._pending !== null;
  }

  _takeNext() {
    const policy = STREAMING_PARSE_POLICY[this._getDeviceType()];
    if (!policy) {
      return this._fifo.shift() || null;
    }
    const next = this._pending;
    this._pending = null;
    return next;
  }

  async _pump() {
    if (this._busy || this._closed) return;
    this._busy = true;

    try {
      while (!this._closed && this._hasWork()) {
        const policy = STREAMING_PARSE_POLICY[this._getDeviceType()];
        const minIntervalMs = policy?.minIntervalMs ?? 0;

        if (minIntervalMs > 0) {
          const wait = minIntervalMs - (Date.now() - this._lastSentAt);
          if (wait > 0) {
            await sleep(wait);
            if (this._closed) break;
          }
        }

        const packet = this._takeNext();
        if (!packet) break;

        this._lastSentAt = Date.now();
        await this._send(packet);
      }
    } finally {
      this._busy = false;
      if (!this._closed && this._hasWork()) {
        queueMicrotask(() => this._pump());
      }
    }
  }
}

/** @param {number} ms */
function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

export default ParseQueue;
