export function resolveProfiles(serverProfiles, allowedDevices) {
  if (serverProfiles?.length) {
    return serverProfiles;
  }
  const allowed = allowedDevices?.length ? allowedDevices : Object.keys(DEVICE_REGISTRY);
  return allowed.map(type => DEVICE_REGISTRY[type]).filter(Boolean);
}

export default DEVICE_REGISTRY;
