/**
 * Auto-reconnect with exponential backoff after unexpected GATT disconnect.
 */
export class ReconnectManager {
  /**
   * @param {{ maxAttempts?: number, baseDelayMs?: number, maxDelayMs?: number }} [options]
   */
  constructor(options = {}) {
    this.maxAttempts = options.maxAttempts ?? 5;
    this.baseDelayMs = options.baseDelayMs ?? 1000;
    this.maxDelayMs = options.maxDelayMs ?? 15000;
    this._attempts = 0;
    this._cancelled = false;
  }

  reset() {
    this._attempts = 0;
    this._cancelled = false;
  }

  cancel() {
    this._cancelled = true;
  }

  /**
   * @param {() => Promise<void>} reconnectFn
   */
  async schedule(reconnectFn) {
    if (this._cancelled || this._attempts >= this.maxAttempts) {
      return false;
    }

    this._attempts += 1;
    const delay = Math.min(this.baseDelayMs * 2 ** (this._attempts - 1), this.maxDelayMs);

    await new Promise(resolve => setTimeout(resolve, delay));

    if (this._cancelled) return false;

    try {
      await reconnectFn();
      this._attempts = 0;
      return true;
    } catch {
      return this.schedule(reconnectFn);
    }
  }
}

export default ReconnectManager;
